using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_89c89141c9bf4776956759a52cee62f6.Auth;

public class HardcodedAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentState;
    private readonly PersistingComponentStateSubscription _subscription;
    private readonly AuthenticationState _authenticationState;

    public HardcodedAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        _persistentState = persistentState;

        var claims = new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        var user = new ClaimsPrincipal(identity);
        _authenticationState = new AuthenticationState(user);

        _subscription = _persistentState.RegisterOnPersisting(OnPersisting, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_authenticationState);

    private Task OnPersisting()
    {
        var user = _authenticationState.User;
        var claims = user.Claims.Select(c => new ClaimInfo(c.Type, c.Value)).ToArray();

        _persistentState.PersistAsJson("UserClaims", claims);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

public record ClaimInfo(string Type, string Value);

