using Microsoft.AspNetCore.Components.Authorization;

namespace sv_89c89141c9bf4776956759a52cee62f6.Client;

public class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _defaultUnauthenticatedTask =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authenticationStateTask = _defaultUnauthenticatedTask;

    public PersistentAuthenticationStateProvider(PersistentComponentState state)
    {
        if (state.TryTakeFromJson<ClaimInfo[]>("UserClaims", out var claimInfos) && claimInfos is not null)
        {
            var claims = claimInfos.Select(c => new Claim(c.Type, c.Value)).ToArray();
            var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
            var user = new ClaimsPrincipal(identity);
            _authenticationStateTask = Task.FromResult(new AuthenticationState(user));
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => _authenticationStateTask;
}

public record ClaimInfo(string Type, string Value);

